#import <Foundation/Foundation.h>
#import <Vision/Vision.h>
#import <ImageIO/ImageIO.h>
int main(int argc,const char *argv[]){@autoreleasepool{if(argc!=2)return 2;NSURL *url=[NSURL fileURLWithPath:@(argv[1])];VNRecognizeTextRequest *request=[VNRecognizeTextRequest new];request.recognitionLevel=VNRequestTextRecognitionLevelAccurate;request.recognitionLanguages=@[@"zh-Hans",@"en-US"];request.usesLanguageCorrection=NO;VNImageRequestHandler *handler=[[VNImageRequestHandler alloc]initWithURL:url options:@{}];NSError *error=nil;if(![handler performRequests:@[request] error:&error]){fprintf(stderr,"OCR failed: %s\n",error.localizedDescription.UTF8String);return 1;}NSMutableArray *out=[NSMutableArray new];for(VNRecognizedTextObservation *o in request.results){VNRecognizedText *t=[o topCandidates:1].firstObject;CGRect b=o.boundingBox;[out addObject:@{@"text":t.string?:@"",@"confidence":@(t.confidence),@"box":@[@(b.origin.x),@(b.origin.y),@(b.size.width),@(b.size.height)]}];}NSData *data=[NSJSONSerialization dataWithJSONObject:out options:0 error:&error];fwrite(data.bytes,1,data.length,stdout);}return 0;}
